window.bookSummaryJSON = "<p><b>Three short horror stories and one piece of nonfiction by Mark Tullius, one of the hardest-hitting authors around.</b></p> <p><b>The tales are bound to leave you more than a touch unsettled.</b></p> <p>Find yourself:</p> <ul> <li>An overweight father ignored by his family</li> <li>A gang member breaking into a neighborhood church</li> <li>A cameraman who finds himself in a hopeless situation</li> <li>An aging author who’s paying the price for a reckless past, doing all he can to repair his brain</li> </ul> <p>These shocking stories will leave you wanting more.</p> <p><b>Scroll up, click on \"Buy Now with 1-Click\", and get your copy now!</b></p>"; 
